<?php get_header(); while(have_posts()):the_post(); $id=get_the_ID(); $price=get_post_meta($id,'_havenstone_price_label',true); $beds=get_post_meta($id,'_havenstone_bedrooms',true); $baths=get_post_meta($id,'_havenstone_bathrooms',true); $parking=get_post_meta($id,'_havenstone_parking',true); $area=get_post_meta($id,'_havenstone_area',true); $address=get_post_meta($id,'_havenstone_address',true); $map=get_post_meta($id,'_havenstone_map_url',true); $agent_id=(int)get_post_meta($id,'_havenstone_agent_id',true); ?>
<main class="property-single site-container section"><a class="back-link" href="<?php echo esc_url(get_post_type_archive_link('property')); ?>">← All properties</a><header><p class="property-single__price"><?php echo esc_html($price); ?></p><h1><?php the_title(); ?></h1><?php if($address): ?><p><?php echo esc_html($address); ?></p><?php endif; ?></header><?php if(has_post_thumbnail()): ?><figure class="property-single__hero"><?php the_post_thumbnail('full',['loading'=>'eager']); ?></figure><?php endif; ?><div class="property-single__facts"><?php foreach([['Bedrooms',$beds],['Bathrooms',$baths],['Parking',$parking],['Area',$area]] as [$label,$value]) if($value!==''): ?><div><strong><?php echo esc_html($value); ?></strong><span><?php echo esc_html($label); ?></span></div><?php endforeach; ?></div><div class="property-single__content"><article><?php the_content(); ?></article><aside><div class="enquiry-card"><h2>Interested in this property?</h2><p>Contact HavenStone Realty to request more details or arrange a viewing.</p><?php if($map): ?><a class="button" href="<?php echo esc_url($map); ?>" target="_blank" rel="noopener">View on map</a><?php endif; ?><a class="button" href="<?php echo esc_url(home_url('/contact/')); ?>">Request a viewing</a></div><?php if($agent_id && get_post_status($agent_id)): ?><div class="agent-card"><h3>Your agent</h3><a href="<?php echo esc_url(get_permalink($agent_id)); ?>"><?php echo esc_html(get_the_title($agent_id)); ?></a></div><?php endif; ?></aside></div></main><?php endwhile; get_footer(); ?>